window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7fb72fdcc88ae3ff"]={"versions": [{"id": "FIG-7fb72fdcc88ae3ff", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des unsegmentierten 1:1-Transfers (Single Frame) im FlexRay Transport Protocol (FrTp) innerhalb der AUTOSAR-Basissoftware (Communication Services).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Sender</strong>: Sendende FrTp-Entität (Transportprotokoll-Knoten auf Senderseite).\n</li><li><strong>Receiver</strong>: Empfangende FrTp-Entität (Transportprotokoll-Knoten auf Empfängerseite).\n</li><li><strong>SF (Single Frame)</strong>: Unsegmentierte N-PDU / FrTp-Nachricht über die FlexRay-Kommunikationsschnittstelle.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Sender initiiert die Übertragung einer unsegmentierten Botschaft und sendet einen Single Frame (<code>SF</code>) direkt an den Receiver.\n</li><li>Der Receiver nimmt den <code>SF</code> entgegen.\n</li><li>Es erfolgt keine Rückmeldung oder Quittierung (ohne Acknowledgement / unacknowledged transfer), womit die Sequenz abgeschlossen ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Spezifiziert den Basisablauf für unsegmentierte 1:1-Nachrichtenübertragung (<code>SF</code>), bei der die Nutzdaten vollständig in eine einzelne N-PDU passen.\n</li><li>Protokollmechanismen für Flusssteuerung (<code>FC</code>), Quittierung (<code>ACK</code>) oder Retransmission entfallen für diesen Transfertyp; Fehlerüberwachung auf Transportebene findet nicht statt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5e591cbdef09e8fc", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des unsegmentierten 1:1-Transfers (Single Frame) im FlexRay Transport Protocol (FrTp) innerhalb der AUTOSAR-Basissoftware (Communication Services).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Sender</strong>: Sendende FrTp-Entität (Transportprotokoll-Knoten auf Senderseite).\n</li><li><strong>Receiver</strong>: Empfangende FrTp-Entität (Transportprotokoll-Knoten auf Empfängerseite).\n</li><li><strong>SF (Single Frame)</strong>: Unsegmentierte N-PDU / FrTp-Nachricht über die FlexRay-Kommunikationsschnittstelle.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Sender initiiert die Übertragung einer unsegmentierten Botschaft und sendet einen Single Frame (<code>SF</code>) direkt an den Receiver.\n</li><li>Der Receiver nimmt den <code>SF</code> entgegen.\n</li><li>Es erfolgt keine Rückmeldung oder Quittierung (ohne Acknowledgement / unacknowledged transfer), womit die Sequenz abgeschlossen ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Spezifiziert den Basisablauf für unsegmentierte 1:1-Nachrichtenübertragung (<code>SF</code>), bei der die Nutzdaten vollständig in eine einzelne N-PDU passen.\n</li><li>Protokollmechanismen für Flusssteuerung (<code>FC</code>), Quittierung (<code>ACK</code>) oder Retransmission entfallen für diesen Transfertyp; Fehlerüberwachung auf Transportebene findet nicht statt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7fb72fdcc88ae3ff", "to": "FIG-5e591cbdef09e8fc", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
